      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "In healthy humans, AMG 579 CSF concentrations were less than 5% of plasma concentrations at all timepoints after oral dosing, directly demonstrating limited CNS access.",
